  "Alla jobb i Pixelstaden – närmast först. 🧭 Visa vägen så pekar en pil dit.": "Al het werk in Pixelstad – het dichtstbij eerst. Tik op 🧭 Wijs de weg, dan wijst een pijl erheen.",
  "Alla kassor är upptagna – jag väntar en stund.": "Alle kassa's zijn bezet – ik wacht even.",
  "Alla katterna här kommer från Tassarnas hem. Vill du adoptera? Fråga där!": "Alle katten hier komen uit het Pootjeshuis. Wil je adopteren? Vraag het daar!",
