  "Du får maten på en bricka och sätter dig vid ett bord eller i fönstret med utsikt över havet. Mättnaden och energin kommer medan du äter – och när allt är uppätet blir du gladare!": "Je krijgt je eten op een dienblad en gaat aan een tafel zitten of bij het raam met uitzicht op zee. Je wordt voller en krijgt energie terwijl je eet – en als alles op is, word je blijer!",
  "Du får maten på en bricka och sätter dig vid ett ledigt bord eller vid fönstret. Mättnaden och energin kommer medan du äter – bara när du sitter!": "Je krijgt het eten op een dienblad en gaat aan een vrije tafel of bij het raam zitten. Het eten en de energie komen terwijl je eet – alleen als je zit!",
