  "Välj din avatar eller skapa en ny.": "Kies je avatar of maak een nieuwe.",
  "Välj en bok. Att läsa ut den tar en timme och ger en utbildningspoäng första gången.": "Kies een boek. Het uitlezen duurt een uur en geeft de eerste keer een studiepunt.",
  "Välj en fröpåse. Vattna bädden varje dag – två dagar utan vatten och plantorna vissnar. Skörden hamnar i skafferiet.": "Kies een zakje zaad. Geef het bed elke dag water – twee dagen zonder water en de plantjes verwelken. De oogst komt in de voorraadkast.",
  "Välj en häst.": "Kies een paard.",
  "Välj en låt – den går hemma tills du stänger av eller lägger dig. Alla låtar i Pixelstaden finns här.": "Kies een nummer – het speelt thuis tot je het uitzet of naar bed gaat. Alle nummers uit Pixelstad staan hier.",
  "Välj en möbel först": "Kies eerst een meubel",
  "Välj en ny frisyr eller färg först.": "Kies eerst een nieuw kapsel of een kleur.",
  "Välj en ny frisyr eller hårfärg – förhandsbilden visar hur det blir på dig.": "Kies een nieuw kapsel of een nieuwe haarkleur – het voorbeeld laat zien hoe het bij jou staat.",
