  "Välj ett märke": "Kies een patch",
  "Välj ett ställe på kartan.": "Kies een plek op de kaart.",
  "Välj färg – en ballong kostar {0}. Den följer med dig på tivolit hela dagen!": "Kies een kleur – een ballon kost {0}. Hij gaat de hele dag met je mee door het pretpark!",
  "Välj hur högt du siktar i varje mål. Du har klarat livet i Pixelstaden när alla fyra är nådda samtidigt.": "Kies hoe hoog je de lat legt voor elk doel. Je hebt het leven in Pixelstad gehaald als alle vier tegelijk bereikt zijn.",
  "Välj hur mycket du vill sätta in.": "Kies hoeveel je wilt storten.",
  "Välj hur mycket du vill ta ut.": "Kies hoeveel je wilt opnemen.",
  "Välj kana. Trapporna upp är branta – håll i räcket.": "Kies een glijbaan. De trappen omhoog zijn steil – hou de leuning vast.",
  "Välj någon i laget – eller skriv ett eget förnamn och nummer.": "Kies iemand uit het team – of typ zelf een voornaam en nummer.",
  "Välj något från menyn först!": "Kies eerst iets van het menu!",
  "Välj något i butiken så slår jag in det!": "Kies iets in de winkel, dan scan ik het!",
  "Välkommen fram!": "Welkom, je bent er!",
  "Välkommen in! Värm upp lite först så går lyften lättare.": "Welkom! Warm eerst even op, dan gaat het heffen makkelijker.",
  "Välkommen in! ✨": "Welkom! ✨",
  "Välkommen ombord! Vad får det lov att vara?": "Welkom aan boord! Wat mag het zijn?",
  "Välkommen till BLIXT!": "Welkom bij FLITS!",
  "Välkommen till Biblioteket! Ta en bok från hyllan och sätt dig vid ett bord. Varje utläst bok ger en utbildningspoäng.": "Welkom in de Bibliotheek! Pak een boek van de plank en ga aan een tafel zitten. Elk uitgelezen boek geeft een studiepunt.",
  "Välkommen till Bio Pixel!": "Welkom bij Bios Pixel!",
  "Välkommen till Gamla stan! Huset bakom mig är från 1699 – titta på årtalet i gaveln.": "Welkom in de Oude Stad! Het huis achter mij is uit 1699 – kijk maar naar het jaartal in de gevel.",
  "Välkommen till Klipp & Klo! Har du ett husdjur så gör vi det jättefint här. ✂️": "Welkom bij Knip & Klauw! Heb je een huisdier, dan maken we het hier prachtig. ✂️",
  "Välkommen till Klipp & Klo! ✂️ Klicka på trimbordet så fixar vi ditt djur.": "Welkom bij Knip & Klauw! ✂️ Klik op de trimtafel, dan maken we je dier mooi.",
  "Välkommen till Kurr! ☕ Fika vid disken – och klappa gärna katterna, de älskar det.": "Welkom bij Snor! ☕ Haal iets lekkers bij de balie – en aai gerust de katten, daar zijn ze dol op.",
  "Välkommen till Museet! Titta på föremålen – skyltarna berättar. När du sett tre stycken får du ta quizet hos mig.": "Welkom in het Museum! Bekijk de voorwerpen – de bordjes vertellen het verhaal. Heb je er drie gezien, dan mag je bij mij de quiz doen.",
  "Välkommen till Pixel Gym! Hantlarna och boxsäcken ger STYRKA, gruppasset KONDITION och dansgolvet RYTM.": "Welkom bij Pixel Gym! De halters en de bokszak geven KRACHT, de groepsles CONDITIE en de dansvloer RITME.",
  "Välkommen till Pixelbanken!": "Welkom bij de Pixelbank!",
