  "🕵️ Ett nytt kapitel i mysteriet väntar – öppna 🔍 Mysteriet i mobilen!": "🕵️ Een nieuw hoofdstuk van het mysterie wacht – open 🔍 Mysterie op je mobiel!",
  "🕵️ Mysteriet är löst – kronan sitter på kattstatyn igen. Du är en mästerdetektiv!": "🕵️ Het mysterie is opgelost – de kroon zit weer op het kattenbeeld. Je bent een meesterspeurder!",
