  "🕹️ Gamingriggarna finns i fyra färger – klicka på en så väljer du modell.": "🕹️ De game-pc's zijn er in vier kleuren – klik op een om een model te kiezen.",
  "🖊️ Blanketter för insättning och uttag. Pennorna sitter fast i kedjor – ingen tar hem en bankpenna.": "🖊️ Formulieren om te storten en op te nemen. De pennen zitten aan kettinkjes – niemand neemt een bankpen mee naar huis.",
  "🖥️ Datorer, TV-apparater och spelkonsoler hamnar i förrådet hemma – ställ ut dem med 🛋️ Möblera.": "🖥️ Computers, tv's en spelcomputers gaan naar je berging thuis – zet ze neer met 🛋️ Inrichten.",
