  "🖨️ Skrivaren surrar och spottar ut ett kontrakt. Fel namn – mäklaren suckar och trycker igen.": "🖨️ De printer zoemt en spuugt een contract uit. Verkeerde naam – de makelaar zucht en drukt nog eens.",
  "🖼️ Albumet är fullt ({0} bilder) – ta bort några i 🖼️ Bilder först.": "🖼️ Het album is vol ({0} foto's) – verwijder eerst een paar in 🖼️ Foto's.",
