  "🖼️ Du fick {0} på köpet – ställ ut den hemma med 🛋️ Möblera, så visar den dina egna designer!": "🖼️ Je kreeg er {0} gratis bij – zet het thuis neer met 🛋️ Inrichten, dan laat het je eigen ontwerpen zien!",
  "🖼️ Fyren på Pixelskär – målad av Majas morfar.": "🖼️ De vuurtoren van Pixeloog – geschilderd door Maaikes opa.",
  "🗂️ Du spelar med samma figur i en annan flik – den här fliken är pausad. Rör den så tar den över igen.": "🗂️ Je speelt met dezelfde figuur in een ander tabblad – dit tabblad is gepauzeerd. Raak het aan en het neemt het weer over.",
  "🗂️ Kortkatalogen: en lapp för varje bok i huset, sorterade för hand. Porträttet är grundaren, Hedvig Bok.": "🗂️ De kaartenbak: een kaartje voor elk boek in het huis, met de hand gesorteerd. Het portret is van de oprichtster, Hendrika Boek.",
  "🗄️ Arkivskåpen är fulla av kontrakt. Nycklarna hänger i skåpet ovanför – en till varje bostad.": "🗄️ De archiefkasten zitten vol contracten. De sleutels hangen in het kastje erboven – één voor elke woning.",
