  "🗺️ Entréplatsen – Sagolandet med karusellen, tekopparna och pariserhjulet – berg-och-dalbanan – radiobilarna – Spökgränd. Marknadsgatan går längs hela parken.": "🗺️ Het entreeplein – Sprookjesland met de draaimolen, de theekopjes en het reuzenrad – de achtbaan – de botsauto's – de Spooksteeg. De Marktstraat loopt langs het hele park.",
