  "🗺️ Tryck på ett ställe: 🧭 en pil visar vägen dit, eller 🚕 ta en taxi.": "🗺️ Tik op een plek: 🧭 een pijl wijst je de weg, of 🚕 neem een taxi.",
  "🗼 Fyren har lyst varje natt sedan 1890. Fyrvaktaren hette Hulda och bodde här med fjorton katter.": "🗼 De vuurtoren schijnt elke nacht sinds 1890. De vuurtorenwachter heette Hulda en woonde hier met veertien katten.",
  "🗼 Solöns fyr har lyst varje natt i över hundra år. Fyrvaktaren sägs ha en båt att hyra ut …": "🗼 De vuurtoren van Zonneland schijnt al meer dan honderd jaar elke nacht. De vuurtorenwachter zou een boot te huur hebben …",
  "🗽 Pixelstadens grundare. Varje vecka får den som skickar flest vänskapspresenter en egen guldstaty här.": "🗽 De stichter van Pixelstad. Elke week krijgt wie de meeste vriendschapscadeautjes stuurt hier een eigen gouden beeld.",
